static void http_connect_bridge(int handle, int result);

/* The engine is a 2012 build that recurses and keeps large buffers on the
 * stack. libnx's main thread only has whatever hbl granted, and unlike an
 * emulator hardware faults the moment it runs off the end. */
#define ENGINE_STACK (8u << 20)

#define SO_GAME     "libgame.so"
#define SO_HERCULES "libHercules.so"

static so_module game_mod;
static so_module herc_mod;
static int hercules_loaded;

/* ------------------------------------------------------------------------- */
/* heap: newlib gets a slice, the rest is the .so staging area               */
/* ------------------------------------------------------------------------- */

static void *heap_so_base = NULL;
static size_t heap_so_limit = 0;
static size_t heap_total = 0;
static size_t heap_newlib = 0;

void __libnx_initheap(void) {
  void *addr = NULL;
  size_t size = 0, mem_available = 0, mem_used = 0;

  if (envHasHeapOverride()) {
    addr = envGetHeapOverrideAddr();
    size = envGetHeapOverrideSize();
  } else {
    svcGetInfo(&mem_available, InfoType_TotalMemorySize, CUR_PROCESS_HANDLE, 0);
    svcGetInfo(&mem_used, InfoType_UsedMemorySize, CUR_PROCESS_HANDLE, 0);
    if (mem_available > mem_used + 0x200000)
      size = (mem_available - mem_used - 0x200000) & ~0x1FFFFF;
    if (size == 0)
      size = 0x2000000 * 16;

    /* Applet mode (launched from the album) hands us far less address space
     * than the docked, game-override path, and svcSetHeapSize rejects the whole
     * request rather than clamping. Walk down until it takes. */
    while (R_FAILED(svcSetHeapSize(&addr, size))) {
      if (size <= 0x6000000)
        diagAbortWithResult(MAKERESULT(Module_Libnx, LibnxError_HeapAllocFailed));
      size = (size / 2) & ~0x1FFFFF;
    }
  }

  extern char *fake_heap_start;
  extern char *fake_heap_end;

  /* Stage the .so at the *top* of the allocation and give newlib everything
   * below it. A fixed cap for newlib (the obvious version) silently left zero
   * bytes for staging whenever the process got less than that cap, which is
   * exactly what happens in applet mode. */
  /* libgame.so stages 7 MB and libHercules is off by default, so a big staging
   * area only starves newlib -- and in applet mode there is not much to starve:
   * 254 MB total. The engine's own asset loading is what needs the room. */
  size_t stage = 24 * 1024 * 1024;
  if (size < stage + 96 * 1024 * 1024)
    stage = ((size / 8) & ~0xFFFFF);
  heap_so_base  = (void *)((char *)addr + size - stage);
  heap_so_limit = stage;

  fake_heap_start = (char *)addr;
  fake_heap_end   = (char *)heap_so_base;

  heap_total  = size;
  heap_newlib = (size_t)((char *)heap_so_base - (char *)addr);
}

