/* The save key, and the two functions that take it as an argument. Installed
 * unconditionally: without it a slot is readable only in the session that wrote
 * it, which is the "my character is gone" failure. */
/* Does the engine's own delete path do anything offline? These three are the
 * cloud-save half of it; logging them separates "the bin button calls the
 * server and waits" from "the bin button does nothing at all". */
static long (*del_check_real)(long);
static long del_check_logged(long slot) {
  debugPrintf("del: CheckExistFromServer(%ld)\n", slot);
  return del_check_real ? del_check_real(slot) : 0;
}

static long (*file_del_real)(void *, void *, void *, void *);
static long file_del_logged(void *a, void *b, void *c, void *d) {
  debugPrintf("del: SAVE_FileDelete(%p, %p)\n", a, b);
  return file_del_real ? file_del_real(a, b, c, d) : 0;
}

